function updateDateTime(){const now=new Date();const weekday=now.toLocaleDateString('en-US',{weekday:'short'});const day=String(now.getDate()).padStart(2,'0');const month=String(now.getMonth()+1).padStart(2,'0');const year=now.getFullYear();const hours=String(now.getHours()).padStart(2,'0');const minutes=String(now.getMinutes()).padStart(2,'0');const seconds=String(now.getSeconds()).padStart(2,'0');const milliseconds=String(now.getMilliseconds()).padStart(3,'0').slice(0,2);const formattedString=`${weekday}, ${day}-${month}-${year} ${hours}:${minutes}:${seconds}:${milliseconds}`;const marquee=document.getElementById('dateTimeMarquee');if(marquee){marquee.textContent=formattedString}}
let timerInterval=null;let isManualPaused=!1;function startTimer(){if(!timerInterval){timerInterval=setInterval(updateDateTime,50)}}
function stopTimer(){clearInterval(timerInterval);timerInterval=null}
updateDateTime();startTimer();const navLine=document.getElementById('navLine');if(navLine){navLine.addEventListener('mouseenter',()=>{if(!isManualPaused){stopTimer();navLine.classList.add('paused')}});navLine.addEventListener('mouseleave',()=>{if(!isManualPaused){updateDateTime();startTimer();navLine.classList.remove('paused')}});navLine.addEventListener('click',()=>{isManualPaused=!isManualPaused;if(isManualPaused){stopTimer();navLine.classList.add('paused')}else{updateDateTime();startTimer();navLine.classList.remove('paused')}})}
function toggleToolsDropdown(e){if(e&&e.stopPropagation)e.stopPropagation();const btn=document.getElementById('toolsBtn');const menu=document.getElementById('toolsMenu');const webringMenu=document.getElementById('dropMenu');if(webringMenu)webringMenu.classList.remove('show');if(menu.classList.contains('show')){menu.classList.remove('show')}else{const rect=btn.getBoundingClientRect();menu.style.position='fixed';menu.style.top=rect.bottom+'px';menu.style.left=(rect.left-2)+'px';menu.style.width='';menu.classList.add('show')}}
function toggleDropdown(e){if(e&&e.stopPropagation)e.stopPropagation();const btn=document.getElementById('dropBtn');const menu=document.getElementById('dropMenu');const toolsMenu=document.getElementById('toolsMenu');if(toolsMenu)toolsMenu.classList.remove('show');if(menu.classList.contains('show')){menu.classList.remove('show')}else{const rect=btn.getBoundingClientRect();menu.style.position='fixed';menu.style.width=rect.width+'px';menu.style.left=rect.left+'px';menu.classList.add('show');const menuHeight=menu.offsetHeight;menu.style.top=(rect.top-menuHeight-4)+'px'}}
window.addEventListener('click',(e)=>{const menu=document.getElementById('dropMenu');const btn=document.getElementById('dropBtn');const toolsMenu=document.getElementById('toolsMenu');const toolsBtn=document.getElementById('toolsBtn');if(menu&&menu.classList.contains('show')&&!btn.contains(e.target)){menu.classList.remove('show')}
if(toolsMenu&&toolsMenu.classList.contains('show')&&!toolsBtn.contains(e.target)){toolsMenu.classList.remove('show')}});function changeWebring(val){const names={'0':'Webring','1':'Foxwells','2':'Kanring','3':'No AI','4':'Octo Ring','5':'Tokukatsu','6':'Roboring',};const sites={'0':'#','1':'https://foxwells.garden/webring/','2':'https://ring.kan.sh','3':'https://baccyflap.com/noai','4':'https://octo-ring.com/','5':'https://tokuring.nekoweb.org','6':'https://stellophiliac.github.io/roboring/',};const prevs={'0':'#','1':'https://foxwells.garden/webring/?prv&s=jokoarynt','2':'https://ring.kan.sh/members/jokoarynt/prev','3':'https://baccyflap.com/noai/?prv&s=jok','4':'https://octo-ring.com/p/jokoarynt/prev','5':'https://tokuring.nekoweb.org?action=previous','6':'https://stellophiliac.github.io/roboring/jokoarynt/previous',};const rnds={'0':'#','1':'https://foxwells.garden/webring/?rnd','3':'https://baccyflap.com/noai/?rnd','4':'https://octo-ring.com/p/jokoarynt/random','5':'https://tokuring.nekoweb.org?action=random',};const nexts={'0':'#','1':'https://foxwells.garden/webring/?nxt&s=jokoarynt','2':'https://ring.kan.sh/members/jokoarynt/next','3':'https://baccyflap.com/noai/?nxt&s=jok','4':'https://octo-ring.com/p/jokoarynt/next','5':'https://tokuring.nekoweb.org?action=next','6':'https://stellophiliac.github.io/roboring/jokoarynt/next',};const actionButtons=document.getElementById('wrActionButtons');const copyrightEl=document.getElementById('copyrightEl');const dropBtn=document.getElementById('dropBtn');if(val==='0'){actionButtons.classList.add('hidden');copyrightEl.classList.remove('hidden');if(dropBtn){dropBtn.style.background='#bfbfbf';dropBtn.style.color='#000'}}else{actionButtons.classList.remove('hidden');copyrightEl.classList.add('hidden');if(dropBtn){dropBtn.style.background='';dropBtn.style.color=''}
document.getElementById('wr-site').href=sites[val]||sites['1'];document.getElementById('wr-prev').href=prevs[val]||prevs['1'];document.getElementById('wr-next').href=nexts[val]||nexts['1'];const rndWrapper=document.getElementById('wr-rnd-wrapper');if(val==='2'||val==='6'){rndWrapper.style.display='none'}else{rndWrapper.style.display='inline-flex';document.getElementById('wr-rnd').href=rnds[val]||rnds['1']}}
document.getElementById('dropLabel').textContent=names[val]||'Webring';const foxwellsImg=document.getElementById('foxwells-img');if(foxwellsImg){foxwellsImg.style.display=(val==='1')?'inline':'none'}
localStorage.setItem('selectedWebring',val);const menu=document.getElementById('dropMenu');if(menu)menu.classList.remove('show');}
function updateThemeIcon(isNight){const icon=document.getElementById('themeIcon');if(!icon)return;if(isNight){icon.innerHTML='<circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line>';icon.setAttribute('fill','none');icon.setAttribute('stroke','currentColor');icon.setAttribute('stroke-width','2')}else{icon.innerHTML='<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path>';icon.setAttribute('fill','#000');icon.removeAttribute('stroke');icon.removeAttribute('stroke-width')}}
function updateGiscusTheme(){const iframe=document.querySelector('iframe.giscus-frame');if(iframe){iframe.contentWindow.postMessage({giscus:{setConfig:{theme:'https://joko.my.id/gb/style.min.css'}}},'https://giscus.app')}}
function toggleTheme(){const isNight=document.documentElement.getAttribute('data-theme')==='night';if(isNight){document.documentElement.removeAttribute('data-theme');localStorage.setItem('theme','light');updateThemeIcon(!1)}else{document.documentElement.setAttribute('data-theme','night');localStorage.setItem('theme','night');updateThemeIcon(!0)}
updateGiscusTheme()}
document.addEventListener('DOMContentLoaded',()=>{const yearEl=document.getElementById('currentYear');if(yearEl){yearEl.textContent=new Date().getFullYear()}
const sizeEl=document.getElementById('s');if(sizeEl){const entry=performance.getEntriesByType('navigation')[0];const size=entry&&entry.encodedBodySize?Math.round(entry.encodedBodySize/1024):0;sizeEl.textContent=size+'kb'}
const savedRing=localStorage.getItem('selectedWebring')||'0';changeWebring(savedRing);const savedTheme=localStorage.getItem('theme');let isNight=!1;if(savedTheme){isNight=(savedTheme==='night')}else{isNight=window.matchMedia('(prefers-color-scheme: dark)').matches}
if(isNight){document.documentElement.setAttribute('data-theme','night');updateThemeIcon(!0)}else{document.documentElement.removeAttribute('data-theme');updateThemeIcon(!1)}
setTimeout(updateGiscusTheme,1500)})
